+// API keys and roles. A request carries `Authorization: Bearer <key>`; keys
+// live in the data as apiKeys [{ key, name, role }].
+import { AppError } from "../errors.js";
+
+const RANK = { viewer: 1, cook: 2, manager: 3 };
+
+// Non-GET routes a cook may use: cook, waste, temperatures, stock-take counts.
+const COOK_ROUTES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The key record for the request's Authorization header; throws unauthorized. */
+export function authenticate(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = /^Bearer\s+(\S+)$/i.exec(String(name ? headers[name] : ""));
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1] && k.role in RANK);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** The lowest role allowed to make this request. */
+function requiredRole(method, path) {
+  if (path === "/audit") return "manager";
+  if (method === "GET") return "viewer";
+  return COOK_ROUTES.some(([m, re]) => m === method && re.test(path)) ? "cook" : "manager";
+}
+
+/** Throws forbidden unless the key's role may make this request. */
+export function authorize(apiKey, method, path) {
+  if (RANK[apiKey.role] < RANK[requiredRole(method, path)]) throw new AppError("forbidden", { role: apiKey.role });
+}
